<template><section class="chat-window-glass" :class="{minimized}"><header class="chat-window-head" @pointerdown="$emit('focus')"><div><b>MAIRA ASSISTANT</b><small><span class="chat-online-dot"/> DEMO DATA · NOT PLATFORM RECORDS</small></div><div class="chat-window-controls"><span class="info-tip" title="Answers come from demo-trained data, not from records in this platform." aria-label="Answers come from demo-trained data, not from records in this platform.">ⓘ</span><IconButton icon="history" label="Conversation history" @click="historyOpen=!historyOpen"/><IconButton icon="minimize" label="Minimize chat" @click="$emit('minimize')"/><IconButton icon="close" label="Close chat" @click="$emit('close')"/></div></header><ChatHistoryPanel v-if="historyOpen" @close="historyOpen=false" @open="openConversation"/><template v-if="!minimized"><div class="chat-window-messages" ref="scroll"><div v-if="loading" class="state-message">Loading conversation…</div><div v-if="error" class="inline-alert">{{error}}</div><div v-else-if="!messages.length" class="chat-empty">Ask Maira a question about land integrity, public services or your documents.</div><article v-for="m in messages" :key="m.id" class="dock-message" :class="m.role"><b>{{m.role==='assistant'?'Maira':'You'}}</b><p>{{m.content}}</p></article></div><div v-if="files.length||documentIds.length" class="dock-chips"><span v-for="f in files" :key="f.name" class="dock-chip"><Icon name="computer"/> {{f.name}} <IconButton icon="cancel" :label="`Remove ${f.name}`" @click="files=files.filter(x=>x!==f)"/></span><span v-for="id in documentIds" :key="id" class="dock-chip"><Icon name="documents"/> {{documentNames[id]||'Stored document'}} <IconButton icon="cancel" :label="`Remove ${documentNames[id]||'stored document'}`" @click="documentIds=documentIds.filter(x=>x!==id)"/></span></div><div class="chat-window-compose"><textarea v-model="query" rows="2" placeholder="Ask Maira…" @keydown.enter.exact.prevent="send"/><div class="dock-compose-actions"><ChatAttachMenu :is-user="role==='User'" @files="addFiles" @documents="pickerOpen=true"/><IconButton :icon="listening ? 'stop' : 'microphone'" :label="listening ? 'Stop voice input' : 'Start voice input'" :variant="listening ? 'danger' : ''" @click="toggleVoice"/><IconButton icon="send" label="Send message" :disabled="!query.trim()&&!files.length&&!documentIds.length" :loading="sending" @click="send"/></div></div></template><DocumentPickerModal v-if="pickerOpen" :model-value="documentIds" :max-selected="5-files.length" @close="pickerOpen=false" @select="selectDocuments"/></section></template>
<script setup lang="ts">import{nextTick,onMounted,ref,watch}from'vue';import api from'@/services/api';import IconButton from'@/components/ui/IconButton.vue';import Icon from'@/components/ui/Icon.vue';import ChatAttachMenu from'./ChatAttachMenu.vue';import DocumentPickerModal from'./DocumentPickerModal.vue';import ChatHistoryPanel from'./ChatHistoryPanel.vue';import{useVoiceInput}from'@/composables/useVoiceInput';
const props=defineProps<{windowId:string;conversationId:string|null;minimized:boolean;role:string}>();const emit=defineEmits<{close:[];minimize:[];created:[id:string];focus:[]}>();const messages=ref<any[]>([]),loading=ref(false),sending=ref(false),error=ref(''),query=ref(''),files=ref<File[]>([]),documentIds=ref<string[]>([]),documentNames=ref<Record<string,string>>({}),pickerOpen=ref(false),historyOpen=ref(false),scroll=ref<HTMLElement|null>(null);const {listening,start,stop}=useVoiceInput(props.windowId,(text)=>query.value+=(query.value?' ':'')+text);
async function load(){if(!props.conversationId)return;loading.value=true;try{const{data}=await api.get(`/v1/chat/conversations/${props.conversationId}`);messages.value=data.messages||[];await nextTick(()=>{if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight})}finally{loading.value=false}}
async function send(){error.value='';if(sending.value||(!query.value.trim()&&!files.value.length&&!documentIds.value.length))return;sending.value=true;try{let response:any;if(files.value.length||documentIds.value.length){const body=new FormData();body.append('query',query.value);files.value.forEach(f=>body.append('files',f));documentIds.value.forEach(id=>body.append('document_ids',id));response=await api.post('/v1/chat/messages-with-files',body,{headers:{...(props.conversationId?{'X-Conversation-ID':props.conversationId}:{}),'Content-Type':'multipart/form-data'}})}else{response=await api.post('/v1/chat/messages',{query:query.value},{headers:props.conversationId?{'X-Conversation-ID':props.conversationId}:{}})}const id=response.headers['x-conversation-id']||props.conversationId;if(id&&!props.conversationId)emit('created',id);query.value='';files.value=[];documentIds.value=[];await load()}catch(e:any){error.value=e.response?.data?.detail||'Unable to reach the assistant. Please try again.'}finally{sending.value=false}}
function addFiles(items:File[]){const combined=files.value.length+documentIds.value.length;if(combined+items.length>5){error.value='Attach at most 5 files.';notify(error.value,'error');return}files.value=[...files.value,...items].slice(0,5-documentIds.value.length)}function selectDocuments(ids:string[],names:Record<string,string>){if(ids.length+files.value.length>5){error.value='Attach at most 5 files.';notify(error.value,'error');return}documentIds.value=ids;documentNames.value=names;pickerOpen.value=false}
async function openConversation(id:string){if(id===props.conversationId){historyOpen.value=false;return}emit('created',id);historyOpen.value=false}
function toggleVoice(){if(listening.value)stop();else start()}
watch(()=>props.conversationId,load);onMounted(load);</script>
